recipes.code:
{
  "inputs": [
    {
      "id": "citadel-key",
      "type": "promptString",
      "description": "Passphrase that derives the AES-256 key encrypting the database region",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "citadeldb-mcp@1.13.0",
        "--db",
        "/absolute/path/to/target"
      ],
      "env": {
        "CITADEL_KEY": "${input:citadel-key}"
      }
    }
  }
}
